const data = $json;

// -----------------------------
// Get sender
// -----------------------------
let from = '';

if (data.from?.value?.[0]) {
  from = data.from.value[0].name || data.from.value[0].address || '';
} else if (typeof data.from === 'string') {
  from = data.from;
}

// -----------------------------
// Get subject
// -----------------------------
let subject = '';

if (typeof data.subject === 'string') {
  subject = data.subject;
} else if (data.subject?.value) {
  subject = String(data.subject.value);
}

// -----------------------------
// Get email body
// -----------------------------
let body = '';

if (typeof data.text === 'string') {
  body = data.text;
} else if (typeof data.html === 'string') {
  body = data.html;
}

// -----------------------------
// Clean HTML
// -----------------------------
body = String(body)
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/<\/p>/gi, ' ')
  .replace(/<\/div>/gi, ' ')
  .replace(/<[^>]*>/g, ' ');

// -----------------------------
// Remove escaped newlines
// -----------------------------
body = body
  .replace(/\\n/g, ' ')
  .replace(/\\r/g, ' ')
  .replace(/\r?\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// -----------------------------
// Remove markdown
// -----------------------------
body = body
  .replace(/\*\*/g, '')
  .replace(/__/g, '')
  .replace(/`/g, '')
  .replace(/^#+\s*/gm, '')
  .trim();

// -----------------------------
// Limit spoken body
// -----------------------------
//if (body.length > 500) {
//  body = body.substring(0, 500) + '...';
//}

// -----------------------------
// Build spoken message
// -----------------------------
let spoken = 'You have a new email';

if (from) {
  spoken += ` from ${from}`;
}

if (subject) {
  spoken += `. Subject: ${subject}`;
}

if (body) {
  spoken += `. ${body}`;
}

spoken += '.';

// Final cleanup
spoken = spoken
  .replace(/\\n/g, ' ')
  .replace(/\\r/g, ' ')
  .replace(/\r?\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return {
  json: {
    ...data,
    sender: from,
    email_subject: subject,
    cleaned_email: body,
    spoken_message: spoken
  }
};
